  openActivityModal=openActivityModalV1;
  openDailyCheckinModal=openMorningCheckinModal;
  openTomorrowPlanModal=async function(){const tomorrow=addDays(isoDate(),1);modal(`<div class="modal-head"><div><h2>Tomorrow</h2><p>The full plan is deliberately set in tomorrow morning's check-in because training can change. You can still leave one useful preparation note now.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="tomorrowNote" class="form-grid"><div class="field"><label>One thing that will make tomorrow easier</label><textarea name="note" placeholder="Put kit out, pack lunch, plan dinner..."></textarea></div><button class="primary-btn wide">Save preparation</button></form>`);document.getElementById('tomorrowNote').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),ex=await HealthDB.get('plans',tomorrow)||{id:tomorrow,date:tomorrow};ex.prepNote=f.get('note').trim();ex.updatedAt=nowIso();await HealthDB.put('plans',ex);closeModal();toast('Tomorrow made easier');};};

  openNutritionModal=async function(){const date=isoDate(),p=state.profile,n=await HealthDB.get('nutrition',date)||{},target=await targetForDate(date);modal(`<div class="modal-head"><div><h2>Nutrition totals</h2><p>Nutracheck remains the food diary. Copy the useful totals here.</p></div><button class="close-btn" data-close-modal>×</button></div><div class="notice">Today's calorie target is <strong>${target?.toLocaleString()||'not set'} kcal</strong>${target&&target!==p.calorieTarget?` because planned training added ${target-p.calorieTarget} kcal to the ${p.calorieTarget} rest-day anchor.`:''}</div><form id="nutritionFormV1" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Calories</label><input type="number" name="calories" value="${n.calories??''}"></div><div class="field"><label>Protein (g)</label><input type="number" name="protein" value="${n.protein??''}"></div><div class="field"><label>Fibre (g)</label><input type="number" name="fibre" value="${n.fibre??''}"></div><div class="field"><label>Fruit & veg</label><input type="number" name="fruitVeg" value="${n.fruitVeg??''}"></div><div class="field"><label>How did eating feel?</label><select name="eatingFeel"><option value="">Not rated</option>${['Easy','Hungry','Snacky','Overate','Very full'].map(x=>`<option ${n.eatingFeel===x?'selected':''}>${x}</option>`).join('')}</select></div></div><button class="primary-btn wide">Save totals</button></form>`);document.getElementById('nutritionFormV1').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),row={id:date,date,calories:num(f.get('calories')),protein:num(f.get('protein')),fibre:num(f.get('fibre')),fruitVeg:num(f.get('fruitVeg')),eatingFeel:f.get('eatingFeel'),source:'manual/nutracheck',updatedAt:nowIso()};await HealthDB.put('nutrition',row);await updateNutritionHabit(date);closeModal();toast('Nutrition totals saved');render();};};

  openSourcesModal=async function(){modal(`<div class="modal-head"><div><h2>Manual data workflow</h2><p>v1.0 is deliberately simple. No account connections, tokens or background sync.</p></div><button class="close-btn" data-close-modal>×</button></div><div class="score-detail-list"><section class="score-detail"><div class="goal-head"><div><strong>⚖ Withings Body+</strong><small>Step on scales → type the morning weight into Morning Check-in.</small></div><span class="pill good">MANUAL</span></div></section><section class="score-detail"><div class="goal-head"><div><strong>⌚ Garmin</strong><small>After exercise, copy distance/time and calories burned. The app learns your personal burn pattern.</small></div><span class="pill good">MANUAL</span></div></section><section class="score-detail"><div class="goal-head"><div><strong>🥗 Nutracheck</strong><small>At the end of the day, copy calories, protein, fibre and fruit/veg totals.</small></div><span class="pill good">MANUAL</span></div></section></div><div class="notice">Automatic sync is parked for a future release. Nothing in v1.0 depends on it.</div>`);};

  dataSourceRows=async function(){return `<div class="source-card"><div class="source-icon">W</div><div><strong>Withings Body+</strong><small>Manual at launch: enter the morning weight during Morning Check-in.</small></div><span class="pill good">MANUAL</span></div><div class="source-card"><div class="source-icon">G</div><div><strong>Garmin Forerunner 945</strong><small>Manual at launch: copy activity distance/time and calories burned after training. Those calories teach the personal burn model.</small></div><span class="pill good">MANUAL</span></div><div class="source-card"><div class="source-icon">N</div><div><strong>Nutracheck</strong><small>Remains your food diary. Copy daily calories, protein, fibre and fruit/veg totals.</small></div><span class="pill good">MANUAL</span></div>`;};
  function calorieTargetHit(calories,target){if(!(Number.isFinite(Number(calories))&&Number(target)>0))return false;const c=Number(calories),t=Number(target);return c>=Math.max(0,t-250)&&c<=t+100;}
  openTodayNumbersModal=async function(){const h=await habitFor();modal(`<div class="modal-head"><div><h2>Steps & water</h2><p>Nutrition has its own Nutracheck totals screen so the adaptive calorie target stays clear.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="numbersV1" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Steps</label><input type="number" name="steps" value="${h.stepsValue??''}" placeholder="${state.profile.stepTarget??''}"></div><div class="field"><label>Water (L)</label><input type="number" step="0.1" name="water" value="${h.waterLitres??''}" placeholder="${state.profile.waterTarget??''}"></div></div><button class="primary-btn wide">Save</button></form>`);document.getElementById('numbersV1').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);h.stepsValue=num(f.get('steps'));h.waterLitres=num(f.get('water'));if(h.stepsValue!=null&&state.profile.stepTarget)h.steps=h.stepsValue>=state.profile.stepTarget;if(h.waterLitres!=null&&state.profile.waterTarget)h.water=h.waterLitres>=state.profile.waterTarget;await saveHabit(h);closeModal();toast('Steps & water updated');render();};};
  setupReadiness=async function(){const p=state.profile,w=await latestMeasurement('weight');return [{label:'Journey dates',detail:`Starts ${fmtDate(p.startDate,{weekday:'short',day:'numeric',month:'short'})}`,done:!!p.startDate&&!!p.madridDate,action:'profile'},{label:'Weight goals',detail:`${p.madridWeight} lb Madrid • ${p.ultimateWeight} lb ultimate`,done:!!p.madridWeight&&!!p.ultimateWeight,action:'profile'},{label:'Starting weight',detail:p.startWeight?`${p.startWeight} lb baseline saved`:(w?`${w.value} lb available — choose baseline`:'Enter Monday morning'),done:!!p.startWeight,action:'baseline'},{label:'Rest-day calorie anchor',detail:p.calorieTarget?`${p.calorieTarget} kcal before training adjustments`:'Set from your real Nutracheck target',done:!!p.calorieTarget,action:'profile'},{label:'Daily targets',detail:(p.stepTarget&&p.proteinTarget&&p.waterTarget)?`${p.stepTarget.toLocaleString()} steps • ${p.proteinTarget}g protein • ${p.waterTarget}L water`:'Set from your real routine',done:!!p.stepTarget&&!!p.proteinTarget&&!!p.waterTarget,action:'profile'},{label:'Garmin / Withings / Nutracheck',detail:'Manual-first workflow ready. No integrations required.',done:true,action:'sources'}];};

  launchPreflight=async function(){const p=state.profile,demo=await HealthDB.get('settings','demoMode'),backup=await HealthDB.get('settings','backupMeta'),lessons=await HealthDB.getAll('lessons');return [{key:'version',label:'Launch candidate installed',detail:`v${APP_VERSION} ${RELEASE_NAME}`,ok:APP_VERSION==='1.0.0-rc3',level:'required'},{key:'demo',label:'Demo data cleared',detail:demo?.active?'TEST DRIVE is still active':'No synthetic demo data active',ok:!demo?.active,level:'required'},{key:'date',label:'Journey date',detail:`Starts Monday 2 November 2026`,ok:p.startDate==='2026-11-02',level:'required'},{key:'goals',label:'Goals set',detail:`${p.madridWeight} lb by Madrid • ${p.ultimateWeight} lb ultimate`,ok:!!p.madridWeight&&!!p.ultimateWeight,level:'required'},{key:'calories',label:'Rest-day calorie anchor',detail:p.calorieTarget?`${p.calorieTarget} kcal base; training adjusts upward from here`:'Set on Day 1 from your real Nutracheck target',ok:!!p.calorieTarget,level:'day1'},{key:'baseline',label:'Starting baseline',detail:p.startWeight?`${p.startWeight} lb already set`:'Correctly waiting for Monday morning',ok:!!p.startWeight,level:'day1'},{key:'backup',label:'Safety backup',detail:backup?.lastBackupAt?`Last encrypted backup ${new Date(backup.lastBackupAt).toLocaleDateString('en-GB')}`:'Make one before clearing demo / starting for real',ok:!!backup?.lastBackupAt,level:'recommended'},{key:'curriculum',label:'Madrid learning programme',detail:`${lessons.length} lessons / review days installed`,ok:lessons.length>=174,level:'required'},{key:'manual',label:'Manual data workflow',detail:'Withings weight + Garmin activities/calories + Nutracheck totals can all be entered manually',ok:true,level:'required'}];};

  // Day 1 onboarding: manual-first + calorie anchor and target loss rate.
  openDayOneOnboarding=async function(preview=false){
    const p=state.profile,supp=await HealthDB.get('settings','supplements')||{id:'supplements',items:['Daily vitamins']},demo=await HealthDB.get('settings','demoMode');
    const defaultAims=(p.journeyAims&&p.journeyAims.length)?p.journeyAims:['lose_weight','maintain','health','energy','running'];
    modal(`<div class="modal-head"><div><h2>${preview?'Preview Day 1':'Day 1 — build the baseline'}</h2><p>${startToMadridDays(p)} days from Monday 2 November to Madrid.</p></div><button class="close-btn" data-close-modal>×</button></div>${preview?'<div class="notice">Preview only — nothing is saved.</div>':''}<form id="dayOneV1" class="form-grid">
      <div class="launch-wizard-section"><div class="wizard-num">1</div><div><h3>Why are you doing this?</h3><p>The coach should protect the reasons behind the numbers.</p></div></div>
      <div class="check-grid">${[['lose_weight','Lose weight'],['maintain','Maintain a lower weight'],['health','Feel healthier'],['energy','Have more energy'],['running','Run well']].map(([k,l])=>`<label class="check-chip"><input type="checkbox" name="aims" value="${k}" ${defaultAims.includes(k)?'checked':''}><span>${l}</span></label>`).join('')}</div>
      <div class="launch-wizard-section"><div class="wizard-num">2</div><div><h3>Are you currently fit and healthy?</h3><p>This sets the first coaching state. Previous test injury/illness history has been cleared.</p></div></div>
      <div class="field"><label>Current health state</label><select name="healthState" id="launchHealthState"><option value="fit">Yes — fit and healthy</option><option value="injury">No — I have an injury / niggle</option><option value="illness">No — I am ill / recovering</option></select></div>
      <div id="launchHealthIssue" style="display:none"><div class="notice warning">This information adapts coaching only. The app does not diagnose injuries or decide what activity is medically safe.</div><div class="form-grid cols-2"><div class="field"><label>Started</label><input type="date" name="healthStartDate" value="${isoDate()}"></div><div class="field"><label>Body area / issue</label><select name="healthArea">${['Ankle','Foot','Lower leg','Knee','Hip','Back','Shoulder / upper body','Illness','Other'].map(v=>`<option>${v}</option>`).join('')}</select></div><div class="field"><label>Side</label><select name="healthSide">${['N/A','Left','Right','Both'].map(v=>`<option>${v}</option>`).join('')}</select></div><div class="field"><label>Severity</label><select name="healthSeverity"><option>Mild</option><option selected>Moderate</option><option>Significant</option></select></div></div><div class="field"><label>How did it happen / what is going on?</label><textarea name="healthCause" placeholder="e.g. rolled ankle playing football; illness symptoms started Friday"></textarea></div><div class="field"><label>What does it affect?</label><div class="check-grid">${[['run','Running'],['walk','Walking'],['stairs','Stairs'],['football','Football / contact'],['gym_lower','Lower-body gym'],['gym_upper','Upper-body gym'],['swim','Swimming'],['cycle','Cycling'],['daily_life','Daily life']].map(([k,l])=>`<label class="check-chip"><input type="checkbox" name="healthAffected" value="${k}"><span>${l}</span></label>`).join('')}</div></div><div class="field"><label>How should training adapt right now?</label><select name="healthRestriction"><option value="modified">Modify training</option><option value="no_run" selected>Pause running</option><option value="recovery">Recovery — no training target</option></select></div><div class="field"><label>Activities I am comfortable doing</label><div class="check-grid">${[['walk','Short walk'],['swim','Swimming'],['cycle','Easy cycling'],['upper_strength','Upper-body weights'],['lower_strength','Lower-body strength'],['mobility','Gentle mobility']].map(([k,l])=>`<label class="check-chip"><input type="checkbox" name="healthAllowed" value="${k}"><span>${l}</span></label>`).join('')}</div></div><div class="field"><label>Anything else the coach should know?</label><textarea name="healthNote" placeholder="What aggravates it, what feels okay, anything you are avoiding..."></textarea></div></div>
      <div class="launch-wizard-section"><div class="wizard-num">3</div><div><h3>Body baseline</h3><p>Reality, not judgement.</p></div></div><div class="form-grid cols-2"><div class="field"><label>Starting weight (lb) *</label><input type="number" step="0.1" name="startWeight" value="${p.startWeight??''}" required></div><div class="field"><label>Waist (in, optional)</label><input type="number" step="0.1" name="waist" value="${p.waist??''}"></div></div>
      <div class="launch-wizard-section"><div class="wizard-num">4</div><div><h3>Weight-loss anchor</h3><p>Your rest-day food target. Training only adjusts upward from this.</p></div></div><div class="form-grid cols-2"><div class="field"><label>Rest-day calories *</label><input type="number" name="calorieTarget" value="${p.calorieTarget??''}" required></div><div class="field"><label>Target loss rate (lb/week)</label><input type="number" step="0.1" min="0.25" max="2" name="targetLossRate" value="${p.targetLossRate??''}" placeholder="e.g. 1.0"></div><div class="field"><label>Protein (g)</label><input type="number" name="proteinTarget" value="${p.proteinTarget??''}"></div><div class="field"><label>Fibre (g)</label><input type="number" name="fibreTarget" value="${p.fibreTarget??''}"></div><div class="field"><label>Water (L)</label><input type="number" step="0.1" name="waterTarget" value="${p.waterTarget??''}"></div><div class="field"><label>Steps</label><input type="number" step="500" name="stepTarget" value="${p.stepTarget??''}"></div></div>
      <div class="launch-wizard-section"><div class="wizard-num">5</div><div><h3>Performance baseline</h3><p>Manual at launch. No Garmin connection needed.</p></div></div><div class="form-grid cols-2"><div class="field"><label>Garmin VO₂ max</label><input type="number" name="vo2max" value="${p.vo2max??''}"></div><div class="field"><label>Typical weekly running (mi)</label><input type="number" step="0.1" name="weeklyRunBaseline" value="${p.weeklyRunBaseline??''}"></div><div class="field"><label>Strength sessions / week</label><input type="number" min="0" max="7" name="strengthTarget" value="${p.strengthTarget??2}"></div><div class="field"><label>Bedtime target</label><input type="time" name="bedtimeTarget" value="${p.bedtimeTarget||'22:30'}"></div></div>
      <div class="launch-wizard-section"><div class="wizard-num">6</div><div><h3>Supplements</h3><p>Adherence only — no dose recommendations.</p></div></div><div class="field"><label>Names, comma separated</label><input name="supplements" value="${esc((supp.items||[]).join(', '))}"></div><div class="notice">When you press Start, Day 1 unlocks and the next screen is Morning Check-in. Any current injury/illness you entered above immediately changes the activity suggestions and coaching.</div><button class="primary-btn wide">${preview?'Finish preview':'Start my journey'}</button></form>`);
    const form=document.getElementById('dayOneV1'),healthSelect=document.getElementById('launchHealthState'),healthBox=document.getElementById('launchHealthIssue');const updateHealthVisibility=()=>{healthBox.style.display=healthSelect.value==='fit'?'none':'block';if(healthSelect.value==='illness')form.elements.healthArea.value='Illness';};healthSelect.onchange=updateHealthVisibility;updateHealthVisibility();
    form.onsubmit=async e=>{e.preventDefault();if(preview){closeModal();toast('Preview complete — nothing saved');return;}const f=new FormData(form),startWeight=num(f.get('startWeight')),calories=num(f.get('calorieTarget'));if(!startWeight||!calories)return;const healthState=f.get('healthState');const updated={...p,startDate:'2026-11-02',startWeight,waist:num(f.get('waist')),calorieTarget:calories,targetLossRate:num(f.get('targetLossRate'))||round((startWeight-p.madridWeight)/(startToMadridDays({...p,startDate:'2026-11-02'})/7),1),proteinTarget:num(f.get('proteinTarget')),fibreTarget:num(f.get('fibreTarget')),waterTarget:num(f.get('waterTarget')),stepTarget:num(f.get('stepTarget')),vo2max:num(f.get('vo2max')),weeklyRunBaseline:num(f.get('weeklyRunBaseline')),strengthTarget:num(f.get('strengthTarget'))??2,bedtimeTarget:f.get('bedtimeTarget'),journeyAims:f.getAll('aims'),launchHealthState:healthState,updatedAt:nowIso()};await HealthDB.put('profile',updated);state.profile=updated;await HealthDB.put('measurements',{id:`weight_${updated.startDate}_launch`,type:'weight',date:updated.startDate,value:startWeight,unit:'lb',source:'launch_baseline',createdAt:nowIso()});if(updated.waist)await HealthDB.put('measurements',{id:`waist_${updated.startDate}_launch`,type:'waist',date:updated.startDate,value:updated.waist,unit:'in',source:'launch_baseline',createdAt:nowIso()});await HealthDB.clear('injuries');if(healthState!=='fit'){const kind=healthState==='illness'?'illness':'injury',area=healthState==='illness'?'Illness':f.get('healthArea');await HealthDB.put('injuries',{id:uid('injury'),kind,startDate:f.get('healthStartDate')||isoDate(),area,side:f.get('healthSide')||'N/A',severity:f.get('healthSeverity')||'Moderate',cause:f.get('healthCause').trim(),affected:f.getAll('healthAffected'),restriction:f.get('healthRestriction')||'modified',allowed:f.getAll('healthAllowed'),note:f.get('healthNote').trim(),active:true,endDate:null,createdAt:nowIso(),updatedAt:nowIso()});}const items=String(f.get('supplements')||'').split(',').map(x=>x.trim()).filter(Boolean);await HealthDB.put('settings',{id:'supplements',items:items.length?items:['Daily vitamins'],updatedAt:nowIso()});await HealthDB.put('settings',{id:'launchMeta',launchedAt:nowIso(),appVersion:APP_VERSION,startDate:updated.startDate,startWeight,demo:!!demo?.active,createdAt:nowIso()});closeModal();toast(healthState==='fit'?'Journey started — set up your first day':'Journey started — coaching adapted to your current health state');setView('today');setTimeout(()=>openMorningCheckinModal(),160);};
  };

  const baseProfileModal=openProfileModal;
  openProfileModal=async function(){const p=state.profile;modal(`<div class="modal-head"><div><h2>Profile & targets</h2><p>The rest-day calorie anchor and target loss rate drive adaptive fuelling.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="profileV1" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Name</label><input name="name" value="${esc(p.name)}"></div><div class="field"><label>Journey start</label><input type="date" name="startDate" value="${p.startDate}"></div><div class="field"><label>Madrid weight (lb)</label><input type="number" step="0.1" name="madridWeight" value="${p.madridWeight}"></div><div class="field"><label>Ultimate weight (lb)</label><input type="number" step="0.1" name="ultimateWeight" value="${p.ultimateWeight}"></div><div class="field"><label>Rest-day calories</label><input type="number" name="calorieTarget" value="${p.calorieTarget??''}"></div><div class="field"><label>Target loss (lb/week)</label><input type="number" step="0.1" min="0.25" max="2" name="targetLossRate" value="${p.targetLossRate??''}"></div><div class="field"><label>Protein (g)</label><input type="number" name="proteinTarget" value="${p.proteinTarget??''}"></div><div class="field"><label>Fibre (g)</label><input type="number" name="fibreTarget" value="${p.fibreTarget??''}"></div><div class="field"><label>Water (L)</label><input type="number" step="0.1" name="waterTarget" value="${p.waterTarget??''}"></div><div class="field"><label>Steps</label><input type="number" step="500" name="stepTarget" value="${p.stepTarget??''}"></div><div class="field"><label>Strength sessions / week</label><input type="number" name="strengthTarget" value="${p.strengthTarget??2}"></div><div class="field"><label>Bedtime</label><input type="time" name="bedtimeTarget" value="${p.bedtimeTarget||'22:30'}"></div></div><button class="primary-btn wide">Save</button></form>`);document.getElementById('profileV1').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);state.profile={...p,name:f.get('name').trim()||'Matt',startDate:f.get('startDate'),madridWeight:num(f.get('madridWeight')),ultimateWeight:num(f.get('ultimateWeight')),calorieTarget:num(f.get('calorieTarget')),targetLossRate:num(f.get('targetLossRate')),proteinTarget:num(f.get('proteinTarget')),fibreTarget:num(f.get('fibreTarget')),waterTarget:num(f.get('waterTarget')),stepTarget:num(f.get('stepTarget')),strengthTarget:num(f.get('strengthTarget')),bedtimeTarget:f.get('bedtimeTarget'),updatedAt:nowIso()};await HealthDB.put('profile',state.profile);closeModal();toast('Targets saved');render();};};

  const baseRenderSettings=renderSettings;
  renderSettings=async function(){let html=await baseRenderSettings();const demo=await HealthDB.get('settings','demoMode'),launch=await launchState();html=html.replace('Use the full dress-rehearsal check before 2 November. It separates true blockers from Day 1 inputs and optional automation.','Use the launch check before Monday 2 November. It separates real blockers from Day 1 inputs.');html=html.replace('Starting weight, waist, Garmin VO₂ max and typical weekly mileage. These can be entered on 2 November morning.','Starting weight, waist, Garmin VO₂ max and typical weekly mileage. These can be entered Monday morning.');html=html.replace('Load a realistic two-week demo so you can test the live dashboard before 2 November.','Load a realistic two-week demo so you can test the complete morning-to-evening loop before launch.');if(demo?.active&&launch?.demo)html=html.replace(/Journey launched [^<]+\./,'🧪 Test journey active — your real journey has not started.');html=html.replace('Garmin + Withings can now use the separate secure connector. Secrets stay out of this public GitHub Pages app; imported records still live locally.','v1.0 is manual-first: enter Withings weight, Garmin activity/calories and Nutracheck totals yourself. Automatic sync is parked for later.');html=html.replace('</section>',`<div class="settings-row"><h3>Calorie & activity model</h3><p>See the rest-day anchor, training adjustments, personal burn learning and weekly calibration.</p><button class="secondary-btn" id="calorieModelSettings">Open calorie model</button></div></section>`);return html;};

  const baseBind=bindViewEvents;
  bindViewEvents=function(){baseBind();const pairs={startRealJourney:openRealLaunchGate,morningCheckin:openMorningCheckinModal,changeTodayPlan:openTodayPlanModal,logActualActivity:()=>openActivityModalV1(),explainCalories:openCalorieModelModal,closeToday:()=>openCloseDayModal(),closeWeek:openCloseWeekModal,viewDailyReport:()=>openDailyReportModal(),calorieModelCard:openCalorieModelModal,runningBurnModel:openCalorieModelModal,calorieModelSettings:openCalorieModelModal};for(const [id,fn] of Object.entries(pairs)){const el=document.getElementById(id);if(el)el.onclick=fn;}const ry=document.getElementById('reviewYesterday');if(ry)ry.onclick=()=>openCloseDayModal(addDays(isoDate(),-1));const dy=document.getElementById('dismissYesterday');if(dy)dy.onclick=async()=>{await HealthDB.put('settings',{id:`dismissUnclosed_${addDays(isoDate(),-1)}`,date:addDays(isoDate(),-1),createdAt:nowIso()});dy.closest('.unclosed-day')?.remove();};HealthDB.get('dailyReports',isoDate()).then(report=>{if(!report)return;document.querySelectorAll('[data-habit-toggle],[data-open-input]').forEach(el=>{el.onclick=()=>{if(confirm('Today is closed. Reopen it to change today’s data?'))HealthDB.remove('dailyReports',isoDate()).then(()=>{toast('Day reopened');render();});};});});};

  openQuickAdd=async function(){const report=await HealthDB.get('dailyReports',isoDate());if(report){openDailyReportModal();return;}modal(`<div class="modal-head"><div><h2>Quick add</h2><p>${report?'Today is closed. Reopen it before changing today’s entries.':'Manual-first: add only the useful outcomes.'}</p></div><button class="close-btn" data-close-modal>×</button></div><div class="quick-grid"><button class="quick-option" data-v1quick="morning"><span>☀️</span><strong>Morning</strong><small>Weight, sleep, plan & calories</small></button><button class="quick-option" data-v1quick="activity"><span>🏃</span><strong>Activity done</strong><small>Distance/time + Garmin calories</small></button><button class="quick-option" data-v1quick="nutrition"><span>🥗</span><strong>Nutrition</strong><small>Nutracheck totals</small></button><button class="quick-option" data-v1quick="vitamins"><span>💊</span><strong>Supplements</strong><small>Tick the list</small></button><button class="quick-option" data-v1quick="numbers"><span>👟</span><strong>Steps & water</strong><small>Manual totals</small></button><button class="quick-option" data-v1quick="plan"><span>↻</span><strong>Change plan</strong><small>Adapt today without failing</small></button><button class="quick-option" data-v1quick="moment"><span>🎯</span><strong>Win / wobble</strong><small>Capture context</small></button><button class="quick-option" data-v1quick="close"><span>🌙</span><strong>Close today</strong><small>Report & bank the day</small></button></div>`);document.querySelectorAll('[data-v1quick]').forEach(b=>b.onclick=()=>{const k=b.dataset.v1quick;closeModal();({morning:openMorningCheckinModal,activity:openActivityModalV1,nutrition:openNutritionModal,vitamins:openSupplementsModal,numbers:openTodayNumbersModal,plan:openTodayPlanModal,moment:openMomentModal,close:()=>openCloseDayModal()}[k])();});};
  document.getElementById('quickAddButton').onclick=openQuickAdd;

  // Dynamic demo data: two weeks ending today, including plans, burns and some closed-day reports.
  loadDemoData=async function(){const existing=await HealthDB.get('settings','demoSnapshot');if(existing){alert('Demo data is already loaded. Reset it first to restart.');return;}if(!confirm('Load a two-week launch demo? Your exact current database is snapshotted first.'))return;try{const snapshot=await HealthDB.exportAll();await HealthDB.put('settings',{id:'demoSnapshot',createdAt:nowIso(),data:snapshot});const start=addDays(isoDate(),-14),original=state.profile||await HealthDB.get('profile','main'),demoProfile={...original,startDate:start,startWeight:216.4,waist:42,vo2max:43,weeklyRunBaseline:18,weeklyRunTarget:20,stepTarget:9000,calorieTarget:1750,targetLossRate:1,proteinTarget:140,fibreTarget:30,waterTarget:2.5,strengthTarget:2,updatedAt:nowIso(),demoMode:true};await HealthDB.put('profile',demoProfile);state.profile=demoProfile;const weights=[216.4,215.9,216.1,215.4,214.9,215.2,214.6,214.2,213.8,214.0,213.4,213.0,212.7,213.4,212.8];for(let i=0;i<15;i++){const date=addDays(start,i),w=weights[i],type=i%4===0?'rest':i%4===1?'run':i%4===2?'gym':'walk',session=type==='run'?{id:`ps_${date}`,type:'run',subtype:i%8===1?'Easy':'Long',distanceMiles:i%8===1?5:8}:type==='gym'?{id:`ps_${date}`,type:'gym',subtype:'Strength',durationMinutes:35}:type==='walk'?{id:`ps_${date}`,type:'walk',subtype:'Brisk',durationMinutes:40}:{id:`ps_${date}`,type:'rest',subtype:'Rest / recovery'};const model=await buildCalorieTarget([session],w,1750);await HealthDB.put('measurements',{id:`demo_weight_${date}`,type:'weight',date,value:w,unit:'lb',source:'demo',createdAt:`${date}T07:00:00.000Z`,demo:true});await HealthDB.put('plans',{id:date,date,sessions:model.details,baseCalorieTarget:1750,trainingAdjustment:model.trainingAdjustment,calorieTarget:model.target,status:'active',morningCompletedAt:`${date}T07:05:00.000Z`,demo:true});const good=i%5!==3;await HealthDB.put('nutrition',{id:date,date,calories:(model.target||1750)+(good?-80:260),protein:good?145:110,fibre:good?31:22,fruitVeg:good?5:3,eatingFeel:good?'Easy':'Snacky',source:'demo',updatedAt:nowIso(),demo:true});await HealthDB.put('checkins',{id:`daily_${date}`,date,sleepHours:6.5+(i%4)*.4,energy:3+(i%3===0?1:0),hunger:good?3:4,body:i%4===2?'Sore':'Normal',mood:'Good',factors:i%6===0?['poor_sleep']:[],morningCompletedAt:`${date}T07:05:00.000Z`,updatedAt:nowIso(),demo:true});const h={id:date,date,weighIn:true,vitamins:i!==4,nutrition:good,protein:good,fibre:good,water:i%5!==2,training:type==='rest'||i%7!==0,steps:i%4!==2,learning:i<10,bedtime:i%4!==0,checkin:true,stepsValue:7800+(i*431)%4200,waterLitres:2.1+(i%3)*.25,updatedAt:nowIso(),demo:true};await HealthDB.put('habits',h);if(type!=='rest'){const burn=type==='run'?(session.distanceMiles*142):type==='gym'?260:190;const act={id:`demo_act_${date}`,date,type,subtype:session.subtype,title:`${session.subtype} ${ACTIVITY_CONFIG[type].label.toLowerCase()}`,distanceMiles:session.distanceMiles||null,durationMinutes:session.durationMinutes||null,caloriesBurned:burn,weightAtActivity:w,source:'demo/garmin',plannedSessionId:session.id,createdAt:`${date}T12:00:00.000Z`,demo:true};await HealthDB.put('activities',act);const pl=await HealthDB.get('plans',date);pl.sessions=pl.sessions.map(s=>({...s,completed:true,actualActivityId:act.id}));await HealthDB.put('plans',pl);}if(i<11){const d=await dailyReportData(date);await HealthDB.put('dailyReports',{id:date,date,score:d.m.earned,tone:d.tone,summary:d.summary,wins:d.wins,misses:d.missing,calories:(await HealthDB.get('nutrition',date)).calories,calorieTarget:model.target,activities:[],closedAt:`${date}T21:30:00.000Z`,demo:true});}}
    const lessons=await HealthDB.getAll('lessons');for(const l of lessons){if(l.day<=10){l.completedAt=`${addDays(start,l.day-1)}T19:00:00.000Z`;l.demoCompleted=true;await HealthDB.put('lessons',l);}}await HealthDB.put('settings',{id:'demoMode',active:true,loadedAt:nowIso(),note:'Synthetic launch demo'});await HealthDB.put('settings',{id:'launchMeta',launchedAt:`${start}T07:00:00.000Z`,appVersion:APP_VERSION,startDate:start,startWeight:216.4,demo:true,createdAt:nowIso()});toast('Launch demo loaded — test the full daily loop');setView('today');}catch(e){console.error(e);alert(`Could not load demo: ${e.message||e}`);}};

