  // Launch-date migration and demo reset hardening.
  const baseResetDemoData=resetDemoData;
  resetDemoData=async function(){
    const snapshot=await HealthDB.get('settings','demoSnapshot');if(!snapshot?.data){alert('No demo snapshot found. There is nothing to reset.');return;}
    if(!confirm('Reset the demo and restore the exact local data from immediately before the demo was loaded?'))return;
    try{await HealthDB.replaceAll(snapshot.data);await ensureDefaults();let p=await HealthDB.get('profile','main');if(p&&p.startDate==='2026-11-03'){p={...p,startDate:'2026-11-02',updatedAt:nowIso()};await HealthDB.put('profile',p);}state.profile=p;toast('Demo removed — clean Monday launch state restored');setView('today');}catch(error){console.error(error);alert(`Could not reset demo data: ${error.message||error}`);}
  };
  async function migrateLaunchCandidate(){const demo=await HealthDB.get('settings','demoMode');let p=await HealthDB.get('profile','main');if(!demo?.active&&p?.startDate==='2026-11-03'){p={...p,startDate:'2026-11-02',updatedAt:nowIso()};await HealthDB.put('profile',p);state.profile=p;}const cfg=await HealthDB.get('settings','connectorConfig');if(cfg?.autoSync){cfg.autoSync=false;cfg.updatedAt=nowIso();await HealthDB.put('settings',cfg);}}

